-- ===========================================================================
-- otbi-atd db/71 : AR Invoice Distribution Details - ALL -- chunked + service
--
-- The saved saljaaidi analysis carried FETCH FIRST 500001 ROWS ONLY *inside
-- the analysis*: every 30-min personal-account load silently truncated a
-- ~575,117-row space to 500,000 (probed 2026-08-16). Converted to the chunked
-- logical-SQL extract (runner/ard_def.py = the generator / single source of
-- truth): 23 chunks partitioning the whole space by construction (dim
-- accounting-date NULL x class + past guard + Dec-2025 x 4 classes w/
-- null-safe catch-alls + 12 monthly 2026 ranges + >= 2027 tail), positional
-- #N headers emitting the job's EXACT colmap headings, min_rows 520,000
-- (proves each run beats the old cap), parallel 4. source_ref becomes a
-- non-catalog token so the db/62 path-owner rule stops selecting the
-- personal c-saljaaidi credential -- runs use the SERVICE account.
-- Deployed 2026-08-16 via python-oracledb (vm180); this script is the
-- rerunnable record. Rollover: extend the 2026 monthly ranges when 2027
-- volume grows (the >= 2027 tail catches everything until then).
-- ===========================================================================
SET DEFINE OFF
SET SQLBLANKLINES ON

UPDATE prod.atd_otbi_jobs
   SET params_json = q'[{"_atd_sql_chunks": {"sql": "SET VARIABLE PREFERRED_CURRENCY='User Preferred Currency 1'; SELECT 0 s_0, \"Receivables - Transactions Real Time\".\"- General Information\".\"Transaction ID\" s_1, \"Receivables - Transactions Real Time\".\"- General Information\".\"Transaction Number\" s_2, \"Receivables - Transactions Real Time\".\"- Line Information\".\"Transaction Line Number\" s_3, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounted\" s_4, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" s_5, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Distribution Percentage\" s_6, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Date\" s_7, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Distribution Comments\" s_8, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Posting Control Id\" s_9, \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"GL Posted Date\" s_10, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Receivables  Code Combination Description\" s_11, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Receivables Concatenated Segments\" s_12, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Alternate Code Combination\" s_13, \"Receivables - Transactions Real Time\".\"- Distribution Combination\".\"Account Type Code\" s_14, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Entered Amount\" s_15, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Distribution Accounted Amount\" s_16, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Ledger Currency\" s_17, \"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Document Currency Name\" s_18, DESCRIPTOR_IDOF(\"Receivables - Transactions Real Time\".\"- Transaction Distributions\".\"Document Currency Name\") s_19, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Update Date\" s_20, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Updated By\" s_21, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Last Updated By User Name\" s_22, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Created By User Name\" s_23, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Creation Date\" s_24, \"Receivables - Transactions Real Time\".\"- Reference Information\".\"Created By\" s_25, \"Receivables - Transactions Real Time\".\"- Distribution Cost Center Segment Value\".\"Distribution Cost Center Description\" s_26, \"Receivables - Transactions Real Time\".\"- Distribution Cost Center Segment Value\".\"Distribution Cost Center Code\" s_27, \"Receivables - Transactions Real Time\".\"- Distribution Natural Account Segment Value\".\"Distribution Natural Account Description\" s_28, \"Receivables - Transactions Real Time\".\"- Distribution Natural Account Segment Value\".\"Distribution Natural Account Code\" s_29 FROM \"Receivables - Transactions Real Time\" WHERE ({chunk})", "chunks": ["\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" IS NULL AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Revenue'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" IS NULL AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Unearned Revenue'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" IS NULL AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Tax'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" IS NULL AND (\"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" NOT IN ('Revenue', 'Unearned Revenue', 'Tax') OR \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" IS NULL)", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2025-12-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Revenue'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Receivable'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Tax'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" = 'Unearned Revenue'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2025-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-01-01' AND (\"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" NOT IN ('Revenue', 'Receivable', 'Tax', 'Unearned Revenue') OR \"Receivables - Transactions Real Time\".\"- Transaction Distribution Details\".\"Accounting Class\" IS NULL)", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-01-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-02-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-02-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-03-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-03-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-04-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-04-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-05-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-05-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-06-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-06-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-07-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-07-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-08-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-08-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-09-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-09-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-10-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-10-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-11-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-11-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2026-12-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2026-12-01' AND \"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" < date '2027-01-01'", "\"Receivables - Transactions Real Time\".\"- Distribution Accounting Date\".\"Accounting Date\" >= date '2027-01-01'"], "headers": {"#2": "Transaction ID", "#3": "Transaction Number", "#4": "Transaction Line Number", "#5": "Accounted", "#6": "Accounting Class", "#7": "Distribution Percentage", "#8": "Accounting Date", "#9": "Distribution Comments", "#10": "Posting Control Identifier", "#11": "Posted Date", "#12": "Receivables  Code Combination Description", "#13": "Receivables Concatenated Segments", "#14": "Alternate Code Combination", "#15": "Account Type Code", "#16": "Distribution Entered Amount", "#17": "Distribution Accounted Amount", "#18": "Ledger Currency", "#19": "Document Currency Name", "#20": "Document Currency", "#21": "Invoice Last Update Date", "#22": "Last Updated By", "#23": "Last Updated By User Name", "#24": "Created By User Name", "#25": "Creation Date", "#26": "Created By", "#27": "Distribution Cost Center Description", "#28": "Distribution Cost Center Code", "#29": "Distribution Natural Account Description", "#30": "Distribution Natural Account Code"}, "min_rows": 520000, "retries": 1, "parallel": 4}}]',
       source_ref = 'chunked-sql: Receivables - Transactions Real Time (AR distributions, 23 chunks)',
       frequency_minutes = 60,
       requested_by = NULL
 WHERE job_name = 'AR Invoice Distribution Details - ALL';

COMMIT;

SELECT job_name, enabled, frequency_minutes, requested_by,
       CASE WHEN params_json IS JSON THEN 'VALID' ELSE 'BAD' END js
  FROM prod.atd_otbi_jobs
 WHERE job_name = 'AR Invoice Distribution Details - ALL';
